"""Design calculations for AB-1 base + HM-1 harvester. Run: python3 calc/design_calcs.py
Writes calc/results.md and calc/results.json. Every input comes from cad/src/params.py or is stated here."""
import json, math, os, sys
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, "..", "cad", "src"))
from params import FIELD, WHEEL, BASE, ARM, HARVESTER_MASS, EE

g = 9.81
out, md = {}, ["# AB-1 / HM-1 design calculations", "",
               "Generated by `calc/design_calcs.py` from `cad/src/params.py`. Inputs are engineering estimates; "
               "items marked *verify* need a bench or field measurement on the first prototype.", ""]

# ---------------------------------------------------------------- 1. mass + centre of gravity
parts = [  # name, mass kg, z of CoG m
    ("deck frame + legs + brackets", BASE["mass_frame"], 0.50),
    ("LFP keel pack 10.75 kWh", BASE["mass_battery"], BASE["keel"]["z_bottom"] + BASE["keel"]["height"] / 2),
    ("4x hub motor + tyre", 4 * BASE["mass_wheel_motor"], WHEEL["radius"]),
    ("electronics enclosure + cooler (under deck)", BASE["mass_enclosure"], BASE["enclosure"]["z_top"] - 0.075),
    ("2x FR5 arm", HARVESTER_MASS["arms"], ARM["mount_z"]),
    ("2x arm controller", HARVESTER_MASS["controllers"], 0.70),
    ("mast + sensors + lights", HARVESTER_MASS["mast"] + HARVESTER_MASS["sensors"] + HARVESTER_MASS["lights"], 1.25),
    ("2x end-effector", HARVESTER_MASS["ee"], 0.95),
    ("2x totes, full (35 kg fruit each)", HARVESTER_MASS["crates_full"], BASE["deck_top_z"] + 0.15),
]
m = sum(p[1] for p in parts)
zc = sum(p[1] * p[2] for p in parts) / m
m_empty = m - 70.0
zc_empty = (zc * m - 70.0 * (BASE["deck_top_z"] + 0.15)) / m_empty
md += ["## 1. Mass budget and centre of gravity", "", "| Item | kg | CoG z (m) |", "|---|---:|---:|"]
md += [f"| {n} | {k:.1f} | {z:.2f} |" for n, k, z in parts]
md += [f"| **Gross (crates full)** | **{m:.0f}** | **{zc:.3f}** |", "",
       f"Empty totes: {m_empty:.0f} kg, CoG z {zc_empty:.3f} m.", ""]
out["mass_gross_kg"], out["cog_z_m"] = round(m), round(zc, 3)

# ---------------------------------------------------------------- 2. static stability
half_track = BASE["track"] / 2
# Arms extended sideways shift CoG laterally: one arm reaching 0.75 m to the side with 1 kg fruit
arm_shift = (ARM["mass"] * 0.35 + 1.0 * (ARM["mount_y"] + ARM["d1"] + 0.75)) / m   # arm mass centroid moves ~0.35 m out
lat_static = math.degrees(math.atan(half_track / zc))
lat_worst = math.degrees(math.atan((half_track - arm_shift) / zc))
long_static = math.degrees(math.atan((BASE["wheelbase"] / 2) / zc))
md += ["## 2. Static stability", "",
       f"- Lateral tip-over angle (arms stowed): **{lat_static:.1f} deg**",
       f"- Lateral tip-over, one arm fully out to the downhill side with fruit: **{lat_worst:.1f} deg** (CoG shift {arm_shift*1000:.0f} mm)",
       f"- Longitudinal tip-over angle: **{long_static:.1f} deg**",
       "- Florida vegetable fields are < 2 deg; the bed shoulder can tilt one side by ~6 deg if a tyre rides up on it. "
       f"Required margin: tip angle >= 3x worst operating tilt (6 deg -> 18 deg). Result: "
       f"{'PASS' if lat_worst >= 18 else 'FAIL'}.",
       "- Software limit: arms may not extend beyond 0.6 m lateral when IMU roll > 8 deg.", ""]
out.update(lat_tip_deg=round(lat_static, 1), lat_tip_worst_deg=round(lat_worst, 1), long_tip_deg=round(long_static, 1))

# ---------------------------------------------------------------- 3. traction + motor sizing
crr_sand, crr_wet = 0.15, 0.25            # loose sand / wet sandy furrow (agricultural tyre literature range)
slope = 0.05
r = WHEEL["radius"]
F_cont = m * g * (crr_sand + slope)
F_peak = m * g * (crr_wet + slope) + m * 0.3 * g   # wet furrow + 0.3 g accel / climbing out of rut
T_cont, T_peak = F_cont * r / 4, F_peak * r / 4
v_work, v_transit = 0.25, 1.5
P_transit = F_cont * v_transit / 0.80
md += ["## 3. Traction and drive motors", "",
       f"- Rolling resistance: Crr {crr_sand} (loose sand), {crr_wet} (wet furrow), +5 % grade.",
       f"- Continuous tractive force {F_cont:.0f} N -> **{T_cont:.0f} N m per wheel** (motor rated 130 N m).",
       f"- Peak (wet furrow + 0.3 g) {F_peak:.0f} N -> **{T_peak:.0f} N m per wheel** (motor peak 200 N m).",
       f"- Traction limit at mu = 0.5 (wet sand): {0.5*m*g:.0f} N > peak demand: {'OK' if 0.5*m*g > F_peak else 'SLIP RISK'}.",
       f"- Drive power at {v_transit} m/s transit: {P_transit:.0f} W total (80 % drivetrain efficiency).",
       f"- Wheel speed at {v_transit} m/s: {v_transit/(2*math.pi*r)*60:.0f} rpm (hub motor runs 45 km/h at 10 in rim, so it is torque-limited, not speed-limited; "
       "run it in FOC current mode with the VESC). *Verify* low-speed torque ripple below 0.1 m/s on the bench.", ""]
out.update(T_cont_Nm=round(T_cont), T_peak_Nm=round(T_peak))

# ---------------------------------------------------------------- 4. power budget + runtime
loads = [  # name, harvesting avg W, transit avg W
    ("drive (4 hub motors, crawl/stop-go while picking)", 250, P_transit),
    ("2x FR5 arm (avg while picking)", 2 * 180, 2 * 40),
    ("Jetson AGX Orin 64GB (MAXN)", 60, 45),
    ("cameras (2 ZED X, 2 D405) + lidar + GNSS + IMU", 35, 25),
    ("network (5G router + mesh radio)", 18, 18),
    ("LED work lights (night ~50 % of hours)", 100, 0),
    ("enclosure thermoelectric cooler (FL summer)", 150, 150),
    ("2x vacuum pump + valves", 30, 0),
    ("EE servos + ring lights", 16, 2),
    ("safety controller, BMS, contactors, misc", 20, 20),
]
P_h = sum(l[1] for l in loads) / 0.95      # DC-DC losses
P_t = sum(l[2] for l in loads) / 0.95
E_pack = 51.2 * 210 / 1000                  # kWh
usable = 0.90 * E_pack
t_h = usable / (P_h / 1000)
charge_kw = 3.5
t_charge = 0.85 * E_pack / charge_kw + 0.25
duty = 24 * t_h / (t_h + t_charge + 0.25)  # 15 min dock in/out
md += ["## 4. Power budget and runtime", "", "| Load | Harvesting W | Transit W |", "|---|---:|---:|"]
md += [f"| {n} | {a:.0f} | {b:.0f} |" for n, a, b in loads]
md += [f"| **Total incl. 5 % DC-DC loss** | **{P_h:.0f}** | **{P_t:.0f}** |", "",
       f"- Pack: 16S2P EVE LF105 = 51.2 V x 210 Ah = **{E_pack:.2f} kWh**, 90 % usable = {usable:.2f} kWh.",
       f"- Runtime harvesting: **{t_h:.1f} h**; transit only: {usable/(P_t/1000):.1f} h.",
       f"- Dock charge at {charge_kw} kW (Delta-Q IC3500-class, CC to 85 % + taper): {t_charge:.1f} h.",
       f"- Achievable duty with autonomous dock charging: **{duty:.1f} h/day** "
       f"(prototype economics assumed 18 h/day with hot swaps; see docs/09_cost_vs_model.md).", ""]
out.update(P_harvest_W=round(P_h), runtime_h=round(t_h, 1), charge_h=round(t_charge, 1), duty_h_day=round(duty, 1),
           pack_kWh=round(E_pack, 2))

# ---------------------------------------------------------------- 5. arm workspace coverage
# Shoulder position for the right arm; fruit sampled across the near half of the row canopy (aisle side).
rng = np.random.default_rng(0)
shoulder = np.array([0.0, ARM["mount_y"] + ARM["d1"], ARM["mount_z"]])
row_y = FIELD["bed_centres"] / 2                 # row centre lateral from aisle centre
N = 20000
fy = row_y - rng.uniform(0.0, FIELD["canopy_half_width"], N)   # near side of canopy (visible from this aisle)
fz = rng.uniform(*FIELD["fruit_z"], N)
fx = rng.uniform(-0.45, 0.45, N)                 # +/-0.45 m along the row per robot stop
pts = np.stack([fx, fy, fz], 1)
reach_eff = ARM["reach"] - EE["tcp_z"] * 0.35 - 0.05    # TCP offset + approach standoff, conservative
d = np.linalg.norm(pts - shoulder, axis=1)
inner = 0.20                                     # shoulder singularity cylinder
cov = np.mean((d < reach_eff) & (d > inner))
md += ["## 5. Arm workspace coverage (fruit band, near half of canopy)", "",
       f"- Shoulder at y = {ARM['mount_y'] + ARM['d1']:.3f} m, z = {ARM['mount_z']} m, side-mounted. Row centre {row_y:.3f} m from aisle centre.",
       f"- Fruit band z {FIELD['fruit_z'][0]}-{FIELD['fruit_z'][1]} m, canopy depth {FIELD['canopy_half_width']} m, "
       f"+/-0.45 m along the row per stop.",
       f"- Effective reach to grasp centre with approach standoff: {reach_eff:.3f} m.",
       f"- **Coverage: {cov*100:.1f} %** of sampled fruit positions are reachable from one stop "
       "(remaining ones are on the far side of the row and get picked from the next aisle).", ""]
out["reach_coverage_pct"] = round(cov * 100, 1)

# ---------------------------------------------------------------- 6. pick cycle time budget
cyc = [("approach from previous fruit (twin-predicted target, no search)", 2.5),
       ("visual servo final 10 cm with D405 (closed loop)", 1.8),
       ("suction engage + finger close (current-limited 3.6 N)", 0.8),
       ("twist 120 deg + pull (detach at calyx, jointless variety)", 1.2),
       ("retract + place in crate (soft drop < 10 cm)", 2.6),
       ("verify + log fruit id in Field Ledger", 0.1)]
t_cyc = sum(c[1] for c in cyc)
per_robot = 2 * 3600 / t_cyc * 0.85      # 2 arms, 85 % arm utilisation (driving between stops)
md += ["## 6. Pick cycle-time budget (per arm)", "", "| Step | s |", "|---|---:|"]
md += [f"| {n} | {s:.1f} |" for n, s in cyc]
md += [f"| **Total per fruit per arm** | **{t_cyc:.1f}** |", "",
       f"- Two arms at 85 % utilisation: **{per_robot:.0f} fruit/h per robot** = {3600/per_robot:.1f} s/fruit robot-level "
       "(prototype sim modelled 8.0 s/fruit twin-guided, so the sim is the conservative case). Published research pickers run 10-25 s/fruit per arm; 9 s/arm is a v1 target to prove on the bench, not a measured number.",
       f"- At 0.20 kg mature-green fruit: {per_robot*0.2:.0f} kg/h; 2 totes (70 kg) fill in "
       f"{70/(per_robot*0.2)*60:.0f} min, so the hauler must swap totes at least that often.", ""]
out.update(cycle_s_per_arm=t_cyc, fruit_per_h=round(per_robot), robot_s_per_fruit=round(3600 / per_robot, 1))

# ---------------------------------------------------------------- 7. wheel ground pressure (sandy soil)
contact_area = 0.12 * WHEEL["width"] * 0.8   # ~120 mm footprint length at 10 psi
p = m * g / 4 / contact_area / 1000
md += ["## 7. Ground pressure", "",
       f"- Per-tyre load {m/4:.0f} kg; footprint ~{contact_area*1e4:.0f} cm2 at 10 psi -> **{p:.0f} kPa** "
       "(human foot ~ 25-60 kPa; tractors 80-150 kPa). Low compaction in the aisle; no beds are driven on.", ""]
out["ground_pressure_kPa"] = round(p)

open(os.path.join(HERE, "results.md"), "w").write("\n".join(md))
json.dump(out, open(os.path.join(HERE, "results.json"), "w"), indent=1)
print(json.dumps(out, indent=1))
